ini_set('display_errors','0'); date_default_timezone_set('Asia/Tehran');
$ROOT=__DIR__.'/../../'; require "$ROOT/lib/Db.php"; require "$ROOT/lib/Jwt.php"; require "$ROOT/lib/Http.php"; require "$ROOT/lib/XlsxWriter.php"; $CONFIG=require "$ROOT/config.php";
function pva_fail($m,$s=400){http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>$m],JSON_UNESCAPED_UNICODE);exit;}
function pva_body(){static $b=null;if($b===null){$b=json_decode(file_get_contents('php://input'),true);if(!is_array($b))$b=[];}return $b;}
function pva_auth(){global $CONFIG;$tok=Http::bearer();$p=$tok?Jwt::verify($tok,$CONFIG['jwt_secret']):null;if(!$p||empty($p['sub']))pva_fail('توکن نامعتبر یا منقضی است',401);$u=Db::one("SELECT u.id,u.is_active,u.is_admin,r.title role_title FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE u.id=? LIMIT 1",[$p['sub']]);if(!$u||!(int)$u['is_active'])pva_fail('کاربر نامعتبر است',401);return $u;}
function pva_norm($s){$s=trim((string)$s);$s=strtr($s,['ي'=>'ی','ى'=>'ی','ك'=>'ک','ۀ'=>'ه','ة'=>'ه','۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);$s=preg_replace('/\s+/u',' ',$s);return trim($s);}
function pva_role($title,$kind=null){$t=pva_norm($title);$isSeniorChief=(mb_strpos($t,'سربازرس')!==false && mb_strpos($t,'ارشد')!==false);if($kind==='check')return $isSeniorChief;if(mb_strpos($t,'گشت موتوری')!==false)return 'motorcycle';if(mb_strpos($t,'گشت خودرویی')!==false)return 'car';if(mb_strpos($t,'سربازرس')!==false)return 'car';return false;}
function pva_allowed($u,$kind=null){return pva_role($u['role_title']??'', $kind);}
function pva_years(){ $y=(int)date('Y')-621; $a=[]; for($x=$y;$x>=1390;$x--)$a[]=$x; return $a; }
function pva_asset($id){return Db::one("SELECT * FROM personnel_vehicle_assets WHERE id=?",[$id]);}
function pva_history($id){return Db::all("SELECT h.id,h.result,h.note,h.checked_at,h.checker_id,u.first_name,u.last_name FROM personnel_vehicle_checklist_history h LEFT JOIN users u ON u.id=h.checker_id WHERE h.asset_id=? ORDER BY h.checked_at DESC,h.id DESC",[$id]);}
function pva_mine($u,$type){$a=Db::one("SELECT * FROM personnel_vehicle_assets WHERE user_id=? AND asset_type=? LIMIT 1",[$u['id'],$type]);if(!$a)return null;$a['photos']=Db::all("SELECT photo_key,data_uri,crop_json FROM personnel_vehicle_asset_photos WHERE asset_id=? ORDER BY id",[$a['id']]);$a['checks']=Db::all("SELECT check_key,check_value,note,checker_id FROM personnel_vehicle_asset_checks WHERE asset_id=?",[$a['id']]);$a['checklist_history']=pva_history($a['id']);return $a;}
function pva_admin_list(){
 $rows=Db::all("SELECT a.*,u.first_name,u.last_name,u.username,u.phone,u.national_code,r.title role_title FROM personnel_vehicle_assets a JOIN users u ON u.id=a.user_id LEFT JOIN roles r ON r.id=u.role_id ORDER BY a.status='pending' DESC,a.updated_at DESC");
 foreach($rows as &$r){$r['photos']=Db::all("SELECT photo_key,data_uri,crop_json FROM personnel_vehicle_asset_photos WHERE asset_id=? ORDER BY id",[$r['id']]);$r['checklist_history']=pva_history($r['id']);}unset($r);return $rows;
}
try{
 $u=pva_auth(); $op=$_GET['op']??'access';
 if($op==='access'){ $role=pva_role($u['role_title']??''); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['allowed'=>$role!==false,'asset_type'=>$role===true?'car':$role,'checklist_allowed'=>pva_allowed($u,'check'),'role_title'=>$u['role_title']??'','years'=>pva_years()],JSON_UNESCAPED_UNICODE); exit; }
 if($op==='mine'){ $type=$_GET['type']??pva_role($u['role_title']??''); if(!in_array($type,['car','motorcycle'],true)||pva_role($u['role_title']??'')!==$type)pva_fail('این بخش برای سمت شما فعال نیست',403); echo json_encode(['asset'=>pva_mine($u,$type)],JSON_UNESCAPED_UNICODE); exit; }
 if($op==='list'){if(!(int)($u['is_admin']??0)&&!pva_allowed($u,'check'))pva_fail('دسترسی مدیریتی لازم است',403);echo json_encode(['items'=>pva_admin_list()],JSON_UNESCAPED_UNICODE);exit;}
 if($op==='save'){ $b=pva_body();$type=$b['asset_type']??'';if(!in_array($type,['car','motorcycle'],true)||pva_role($u['role_title']??'')!==$type)pva_fail('دسترسی ثبت وسیله برای سمت شما مجاز نیست',403);$years=pva_years();$year=(int)pva_norm($b['model_year']??0);if($year<1390||!in_array($year,$years,true))pva_fail('سال ساخت نامعتبر است');
  $cols=['asset_type','plate_part_right','plate_letter','plate_part_left','plate_iran','motorcycle_plate_top','motorcycle_plate_bottom','vehicle_type','fuel_type','color','model_year','chassis_number','engine_number','vin','motorcycle_usage','motorcycle_system','motorcycle_type','cylinders','license_number','license_issue_date','license_expiry_date','insurance_number','insurance_company','insurance_issue_date','insurance_expiry_date','technical_inspection_number','technical_inspection_issue_date','technical_inspection_expiry_date','fixed_beacon','mobile_beacon','heating_ok','cooling_ok','amplifier'];$vals=[];foreach($cols as $c){$v=$b[$c]??null;if(in_array($c,['model_year','cylinders','fixed_beacon','mobile_beacon','heating_ok','cooling_ok','amplifier'],true))$v=($v===''||$v===null)?null:(int)pva_norm($v);$vals[]=$v;}
  $old=Db::one("SELECT id FROM personnel_vehicle_assets WHERE user_id=? AND asset_type=?",[$u['id'],$type]);if($old){$sets=[];foreach($cols as $c){$sets[]="`$c`=?";}$sets[]="status='pending'";$sets[]="verified_by=NULL";$sets[]="verified_at=NULL";Db::query("UPDATE personnel_vehicle_assets SET ".implode(',',$sets)." WHERE id=?",array_merge($vals,[$old['id']]));$id=(int)$old['id'];}else{$names=implode(',',array_map(fn($x)=>"`$x`",array_merge(['user_id'],$cols)));$qs=implode(',',array_fill(0,count($vals)+1,'?'));Db::query("INSERT INTO personnel_vehicle_assets ($names,status) VALUES ($qs,'pending')",array_merge([$u['id']],$vals));$id=(int)Db::lastInsertId();}
  $photos=$b['photos']??[];if(is_array($photos)){foreach($photos as $ph){$key=trim((string)($ph['photo_key']??''));$data=(string)($ph['data_uri']??'');if($key===''||$data==='')continue;if(strlen($data)>9000000)pva_fail('حجم یکی از تصاویر بیش از حد مجاز است');$crop=json_encode($ph['crop_meta']??null,JSON_UNESCAPED_UNICODE);Db::query("INSERT INTO personnel_vehicle_asset_photos(asset_id,photo_key,data_uri,crop_json) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE data_uri=VALUES(data_uri),crop_json=VALUES(crop_json),updated_at=CURRENT_TIMESTAMP",[$id,$key,$data,$crop]);}}
  echo json_encode(['ok'=>true,'asset'=>pva_mine($u,$type)],JSON_UNESCAPED_UNICODE);exit;
 }
 if($op==='checklist-list'){if(!pva_allowed($u,'check'))pva_fail('فقط سربازرس ارشد دسترسی دارد',403);echo json_encode(['items'=>pva_admin_list()],JSON_UNESCAPED_UNICODE);exit;}
 if($op==='checklist-verify'){if(!pva_allowed($u,'check'))pva_fail('فقط سربازرس ارشد دسترسی دارد',403);$b=pva_body();$id=(int)($b['asset_id']??0);$asset=pva_asset($id);if(!$asset)pva_fail('وسیله یافت نشد',404);$checks=is_array($b['checks']??null)?$b['checks']:[];foreach($checks as $k=>$v){Db::query("INSERT INTO personnel_vehicle_asset_checks(asset_id,checker_id,check_key,check_value,note) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE check_value=VALUES(check_value),note=VALUES(note),updated_at=CURRENT_TIMESTAMP",[$id,$u['id'],(string)$k,!empty($v['value'])?1:0,(string)($v['note']??'')]);}$status=!empty($b['approved'])?'verified':'needs_correction';$note=(string)($b['note']??'');Db::query("INSERT INTO personnel_vehicle_checklist_history(asset_id,checker_id,result,note,checked_at) VALUES(?,?,?,?,NOW())",[$id,$u['id'],$status,$note]);Db::query("UPDATE personnel_vehicle_assets SET status=?,verified_by=?,verified_at=NOW(),checklist_note=? WHERE id=?",[$status,$u['id'],$note,$id]);echo json_encode(['ok'=>true,'status'=>$status,'checked_at'=>date('Y-m-d H:i:s')],JSON_UNESCAPED_UNICODE);exit;}
 if($op==='export'){if(!(int)($u['is_admin']??0) && !pva_allowed($u,'check'))pva_fail('دسترسی مدیریتی لازم است',403);$rows=Db::all("SELECT a.*,u.first_name,u.last_name,u.username,u.phone,u.national_code,r.title role_title FROM personnel_vehicle_assets a JOIN users u ON u.id=a.user_id LEFT JOIN roles r ON r.id=u.role_id ORDER BY u.last_name,u.first_name,a.asset_type");$photoKeys=[];foreach($rows as $r){$ps=Db::all("SELECT photo_key FROM personnel_vehicle_asset_photos WHERE asset_id=?",[$r['id']]);foreach($ps as $p){$k=(string)$p['photo_key'];if($k!==''&&!in_array($k,$photoKeys,true))$photoKeys[]=$k;}}$head=['شناسه','نام','نام خانوادگی','نام کاربری','سمت','موبایل','کد ملی','نوع وسیله','پلاک','نوع خودرو','سوخت','رنگ','سال ساخت','شماره شاسی/تنه','شماره موتور','VIN','سیستم موتور','تیپ موتور','کاربری موتور','سیلندر','شماره گواهینامه','صدور گواهینامه','انقضای گواهینامه','شماره بیمه','شرکت بیمه','صدور بیمه','انقضای بیمه','شماره معاینه فنی','صدور معاینه','انقضای معاینه','چراغگردان ثابت','چراغگردان متحرک','گرمایش','سرمایش','آمپلی‌فایر','وضعیت بررسی','اولین تاریخ چک‌لیست','آخرین تاریخ چک‌لیست','تاریخچه کامل چک‌لیست'];foreach($photoKeys as $k)$head[]='تصویر '.$k;$x=new XlsxWriter($head);foreach($rows as $r){$history=pva_history($r['id']);$dates=[];$first=null;$last=null;foreach($history as $h){$dates[]=$h['checked_at'];$first=$first===null?$h['checked_at']:$first;$last=$last===null?$h['checked_at']:$last;}$plate=$r['asset_type']==='motorcycle'?trim(($r['motorcycle_plate_top']??'').' / '.($r['motorcycle_plate_bottom']??'')):trim(($r['plate_part_right']??'').' '.($r['plate_letter']??'').' '.($r['plate_part_left']??'').' ایران '.($r['plate_iran']??''));$cells=[$r['id'],$r['first_name'],$r['last_name'],$r['username'],$r['role_title'],$r['phone'],$r['national_code'],$r['asset_type']==='car'?'خودرو':'موتورسیکلت',$plate,$r['vehicle_type'],$r['fuel_type'],$r['color'],$r['model_year'],$r['chassis_number'],$r['engine_number'],$r['vin'],$r['motorcycle_system'],$r['motorcycle_type'],$r['motorcycle_usage'],$r['cylinders'],$r['license_number'],$r['license_issue_date'],$r['license_expiry_date'],$r['insurance_number'],$r['insurance_company'],$r['insurance_issue_date'],$r['insurance_expiry_date'],$r['technical_inspection_number'],$r['technical_inspection_issue_date'],$r['technical_inspection_expiry_date'],((int)$r['fixed_beacon']?'بله':'خیر'),((int)$r['mobile_beacon']?'بله':'خیر'),((int)$r['heating_ok']?'بله':'خیر'),((int)$r['cooling_ok']?'بله':'خیر'),((int)$r['amplifier']?'بله':'خیر'),$r['status'],$first,$last,implode(' | ',$dates)];$photos=Db::all("SELECT photo_key,data_uri FROM personnel_vehicle_asset_photos WHERE asset_id=? ORDER BY id",[$r['id']]);$byKey=[];foreach($photos as $ph)$byKey[(string)$ph['photo_key']]=$ph;$imageStart=count($cells);foreach($photoKeys as $k)$cells[]='';$row=$x->addRow($cells);foreach($photoKeys as $idx=>$k){$bytes=(string)($byKey[$k]['data_uri']??'');if(strpos($bytes,'base64,')!==false)$bytes=substr($bytes,strpos($bytes,'base64,')+7);$bytes=preg_replace('/\s+/','',$bytes);$bytes=base64_decode($bytes,true);if($bytes!==false&&$bytes!==''){$x->setImage($row,$imageStart+$idx,$bytes,110);$x->setColWidth($imageStart+$idx,18);}}}$x->output('personnel_vehicle_assets.xlsx','اطلاعات خودروها و موتورها');exit;}
 pva_fail('عملیات نامعتبر',404);
}catch(Throwable $e){error_log('personnel-vehicle-assets: '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine());pva_fail('خطای داخلی سرویس اطلاعات خودرو/موتور',500);}
